#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>

using namespace std;

/**
 * An Easy Problem! (一個簡單的問題)
 * 給定一個 N 進位的數 R，已知 R 能被 N-1 整除，求最小的 N (2 <= N <= 62)。
 * 
 * 數學性質：
 * 一個數在 N 進位下可表示為 sum(d_i * N^i)。
 * sum(d_i * N^i) ≡ sum(d_i * 1^i) ≡ sum(d_i) (mod N-1)。
 * 因此，若 R 能被 N-1 整除，則其數位之和 sum(d_i) 也能被 N-1 整除。
 */

// 將字元轉換為對應的數值 (0-9: 0-9, A-Z: 10-35, a-z: 36-61)
int charToValue(char c) {
    if (isdigit(c)) return c - '0';
    if (isupper(c)) return c - 'A' + 10;
    if (islower(c)) return c - 'a' + 36;
    return -1;
}

int main() {
    string r;
    // 讀取大數 R (字串形式)
    while (cin >> r) {
        int maxDigitValue = 1; // 最小進位至少是 2，對應最大數位值 1
        long long sumOfDigits = 0;

        for (char c : r) {
            int v = charToValue(c);
            if (v == -1) continue; // 跳過非數位字元
            sumOfDigits += v;
            if (v > maxDigitValue) maxDigitValue = v;
        }

        bool found = false;
        // 測試所有可能的進位 N (從 maxDigitValue + 1 開始到 62)
        for (int n = maxDigitValue + 1; n <= 62; ++n) {
            // 檢查數位之和是否能被 N-1 整除
            if (sumOfDigits % (n - 1) == 0) {
                cout << n << endl;
                found = true;
                break;
            }
        }

        if (!found) {
            cout << "such number is impossible!" << endl;
        }
    }
    return 0;
}
